#include <array>
#include <cstddef>
#include <iostream>
#include <memory_resource>
#include <numeric>
#include <vector>

int main()
{
    alignas(std::max_align_t) std::array<std::byte, 1024> buffer{};
    std::pmr::monotonic_buffer_resource arena{buffer.data(), buffer.size()};
    {
        std::pmr::vector<int> counts{&arena};
        counts.reserve(3);
        counts.push_back(2);
        counts.push_back(3);
        counts.push_back(4);
        std::cout << std::accumulate(counts.begin(), counts.end(), 0) << '\n';
    }
    arena.release();
}
